package hn.uth.pm1ea0199.controller;
import android.app.*;import android.os.*;import android.content.*;import android.text.InputType;import android.widget.*;import java.io.*;import hn.uth.pm1ea0199.dao.ContactoDAO;import hn.uth.pm1ea0199.model.Contacto;import hn.uth.pm1ea0199.view.Vistas;
public class RegistroActivity extends Activity {
 private ContactoDAO dao;private Spinner pais;private EditText nombre,telefono,nota;private ImageView foto;private long id=-1;private String imagen="";private String original="";
 private final String[] paises={"Honduras (504)","Costa Rica (506)","Guatemala (502)","El Salvador (503)","Nicaragua (505)","Panamá (507)","Belice (501)"};
 @Override public void onCreate(Bundle s){super.onCreate(s);dao=new ContactoDAO(this);id=getIntent().getLongExtra("id",-1);
 ScrollView scroll=new ScrollView(this);LinearLayout l=Vistas.pagina(this,"");scroll.setFillViewport(true);scroll.addView(l);setContentView(scroll);
 TextView uth=new TextView(this);uth.setText("UTH");uth.setTextSize(22);uth.setTypeface(null,android.graphics.Typeface.BOLD);uth.setTextColor(android.graphics.Color.rgb(0,130,50));uth.setGravity(android.view.Gravity.CENTER);uth.setPadding(0,0,0,10);l.addView(uth);
 foto=Vistas.foto(this,l);foto.setOnClickListener(v->elegirFoto());Button camara=Vistas.boton(this,l,"📷  Tomar / seleccionar fotografía");camara.setOnClickListener(v->elegirFoto());
 Vistas.etiqueta(this,l,"País");pais=new Spinner(this);pais.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,paises));pais.setBackground(Vistas.fondo(android.graphics.Color.WHITE,android.graphics.Color.rgb(50,120,220),0));l.addView(pais,new LinearLayout.LayoutParams(-1,Vistas.dp(this,44)));
 nombre=Vistas.campo(this,l,"Nombre",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);
 telefono=Vistas.campo(this,l,"Teléfono",InputType.TYPE_CLASS_PHONE);
 nota=Vistas.campo(this,l,"Nota",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|InputType.TYPE_TEXT_FLAG_MULTI_LINE);nota.setSingleLine(false);nota.setGravity(android.view.Gravity.TOP);nota.setTextColor(android.graphics.Color.BLACK);nota.setBackground(Vistas.fondo(android.graphics.Color.rgb(185,215,166),android.graphics.Color.DKGRAY,Vistas.dp(this,14)));nota.setLayoutParams(new LinearLayout.LayoutParams(-1,Vistas.dp(this,85)));
 Vistas.principal(this,l,id<0?"Salvar Contacto":"Guardar cambios",android.graphics.Color.rgb(0,155,35)).setOnClickListener(v->guardar());
 Vistas.principal(this,l,id<0?"Contactos Salvados":"Cancelar",android.graphics.Color.rgb(45,119,216)).setOnClickListener(v->{if(id>=0)finish();else startActivity(new Intent(this,ListaActivity.class));});
 if(id>=0){Contacto c=dao.buscar(id);if(c==null){finish();return;}nombre.setText(c.nombre);telefono.setText(c.telefono);nota.setText(c.nota);imagen=c.imagen;original=imagen;for(int n=0;n<paises.length;n++)if(paises[n].equals(c.pais)||paises[n].startsWith(c.pais+" ("))pais.setSelection(n);}
 if(s!=null){imagen=s.getString("imagen",imagen);original=s.getString("original",original);nombre.setText(s.getString("nombre",""));telefono.setText(s.getString("telefono",""));nota.setText(s.getString("nota",""));pais.setSelection(s.getInt("pais",0));}Vistas.mostrar(foto,imagen);
 }
 @Override protected void onSaveInstanceState(Bundle s){s.putString("imagen",imagen);s.putString("original",original);s.putString("nombre",nombre.getText().toString());s.putString("telefono",telefono.getText().toString());s.putString("nota",nota.getText().toString());s.putInt("pais",pais.getSelectedItemPosition());super.onSaveInstanceState(s);}
 private void elegirFoto(){new AlertDialog.Builder(this).setTitle("Fotografía del contacto").setItems(new String[]{"Tomar fotografía","Seleccionar de galería"},(d,op)->{try{if(op==0)startActivityForResult(new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE),11);else{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);}}catch(ActivityNotFoundException e){Vistas.alerta(this,"No hay una aplicación disponible para esta opción.");}}).show();}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==11&&result==RESULT_OK&&data!=null&&data.getExtras()!=null){Object obj=data.getExtras().get("data");if(obj instanceof android.graphics.Bitmap){File archivo=null;try{File dir=new File(getFilesDir(),"fotos");if(!dir.exists()&&!dir.mkdirs())throw new IOException();archivo=File.createTempFile("camara_",".png",dir);try(OutputStream out=new FileOutputStream(archivo)){if(!((android.graphics.Bitmap)obj).compress(android.graphics.Bitmap.CompressFormat.PNG,100,out))throw new IOException();}borrarTemporal();imagen=archivo.getAbsolutePath();Vistas.mostrar(foto,imagen);}catch(Exception e){if(archivo!=null)archivo.delete();Vistas.alerta(this,"No se pudo guardar la fotografía.");}}return;}if(r==10&&result==RESULT_OK&&data!=null&&data.getData()!=null){File f=null;try{File dir=new File(getFilesDir(),"fotos");if(!dir.exists()&&!dir.mkdirs())throw new IOException();f=File.createTempFile("contacto_",".img",dir);try(InputStream in=getContentResolver().openInputStream(data.getData());OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(o.outWidth<=0)throw new IOException();borrarTemporal();imagen=f.getAbsolutePath();Vistas.mostrar(foto,imagen);}catch(Exception e){if(f!=null)f.delete();Vistas.alerta(this,"No se pudo leer la fotografía. Selecciona otra imagen.");}}}
 private void borrarTemporal(){if(!imagen.isEmpty()&&!imagen.equals(original))new File(imagen).delete();}
 private void guardar(){String n=nombre.getText().toString().trim(),t=telefono.getText().toString().trim(),o=nota.getText().toString().trim();if(n.isEmpty()){Vistas.alerta(this,"Debe escribir un nombre");return;}if(t.isEmpty()){Vistas.alerta(this,"Debe escribir un teléfono de 8 dígitos");return;}if(o.isEmpty()){Vistas.alerta(this,"Debe escribir una nota");return;}if(imagen.isEmpty()){Vistas.alerta(this,"Debe tomar o seleccionar una fotografía");return;}if(!n.matches("[\\p{L}\\p{M}]+(?: +[\\p{L}\\p{M}]+)*")){nombre.setError("El nombre debe contener solo letras y espacios.");return;}if(!t.matches("[0-9]{8}")){telefono.setError("Ingresa exactamente 8 dígitos.");return;}try{Contacto c=new Contacto(id,pais.getSelectedItem().toString(),n,t,o,imagen);if(id<0)dao.guardar(c);else if(!dao.actualizar(c))throw new IllegalStateException();if(!original.isEmpty()&&!original.equals(imagen))new File(original).delete();original=imagen;Toast.makeText(this,"Contacto guardado",Toast.LENGTH_SHORT).show();if(id>=0){finish();return;}nombre.setText("");telefono.setText("");nota.setText("");pais.setSelection(0);imagen="";original="";foto.setImageResource(android.R.drawable.ic_menu_myplaces);}catch(Exception e){Vistas.alerta(this,"No se pudo guardar el contacto.");}}
 @Override protected void onDestroy(){if(isFinishing())borrarTemporal();dao.close();super.onDestroy();}
}
